"""kitty: track shared expenses on group trips and work out who owes whom."""
import sys

from kitty.cli import main

sys.exit(main())
import argparse
import csv
import json
import sys

from kitty.errors import KittyError
from kitty.ledger import Kitty

EXPORT_COLUMNS = ["id", "date", "payer", "description", "amount", "currency",
                  "category", "base_amount"]


class Parser(argparse.ArgumentParser):
    """ArgumentParser that exits with status 1 (not 2) on usage errors."""

    def error(self, message):
        self.print_usage(sys.stderr)
        print(f"error: {message}", file=sys.stderr)
        sys.exit(1)


def build_parser():
    parser = Parser(prog="python3 -m kitty",
                    description="Track shared expenses on group trips.")
    commands = parser.add_subparsers(dest="command", metavar="COMMAND", required=True)

    p = commands.add_parser("init", help="start a new kitty")
    p.add_argument("currency", help="base currency, e.g. EUR")

    member = commands.add_parser("member", help="manage group members")
    member_cmds = member.add_subparsers(dest="action", metavar="ACTION", required=True)
    member_cmds.add_parser("add", help="add a member").add_argument("name")
    member_cmds.add_parser("remove", help="remove a member").add_argument("name")
    member_cmds.add_parser("list", help="list members")

    expense = commands.add_parser("expense", help="manage expenses")
    expense_cmds = expense.add_subparsers(dest="action", metavar="ACTION", required=True)
    p = expense_cmds.add_parser("add", help="record an expense")
    p.add_argument("payer")
    p.add_argument("amount")
    p.add_argument("description")
    p.add_argument("--among", metavar="A,B", help="split equally among only these people")
    p.add_argument("--exact", metavar="A=30,B=20", help="split by exact amounts")
    p.add_argument("--shares", metavar="A=2,B=1", help="split by shares")
    p.add_argument("--percent", metavar="A=60,B=40", help="split by percentages")
    p.add_argument("--currency", help="currency paid in (default: base currency)")
    p.add_argument("--date", help="YYYY-MM-DD (default: today)")
    p.add_argument("--category", help="category (default: other)")
    expense_cmds.add_parser("list", help="list expenses")
    expense_cmds.add_parser("remove", help="remove an expense").add_argument("id")

    payment = commands.add_parser("payment", help="record repayments")
    payment_cmds = payment.add_subparsers(dest="action", metavar="ACTION", required=True)
    p = payment_cmds.add_parser("add", help="record FROM paying TO back")
    p.add_argument("sender", metavar="FROM")
    p.add_argument("recipient", metavar="TO")
    p.add_argument("amount")
    p.add_argument("--currency", help="currency paid in (default: base currency)")
    p.add_argument("--date", help="YYYY-MM-DD (default: today)")

    rate = commands.add_parser("rate", help="manage exchange rates")
    rate_cmds = rate.add_subparsers(dest="action", metavar="ACTION", required=True)
    p = rate_cmds.add_parser("set", help="set how much one unit is worth in the base currency")
    p.add_argument("currency")
    p.add_argument("rate")

    commands.add_parser("balances", help="show each person's balance")
    commands.add_parser("settle", help="suggest payments to square everyone up")
    commands.add_parser("history", help="show everything affecting one person").add_argument("name")
    commands.add_parser("report", help="show each person's spending per category")
    commands.add_parser("export", help="export expenses to CSV").add_argument("file")
    return parser


def emit(value):
    print(json.dumps(value, indent=2, ensure_ascii=False))


def run(args):
    if args.command == "init":
        Kitty.create(args.currency)
        return

    kitty = Kitty.load()
    command = (args.command, getattr(args, "action", None))

    if command == ("member", "add"):
        kitty.add_member(args.name)
    elif command == ("member", "remove"):
        kitty.remove_member(args.name)
    elif command == ("member", "list"):
        return emit(kitty.members)
    elif command == ("expense", "add"):
        expense_id = kitty.add_expense(
            args.payer, args.amount, args.description, among=args.among, exact=args.exact,
            shares=args.shares, percent=args.percent, currency=args.currency,
            when=args.date, category=args.category)
        kitty.save()
        print(expense_id)
        return
    elif command == ("expense", "list"):
        return emit(kitty.list_expenses())
    elif command == ("expense", "remove"):
        kitty.remove_expense(args.id)
    elif command == ("payment", "add"):
        kitty.add_payment(args.sender, args.recipient, args.amount,
                          currency=args.currency, when=args.date)
    elif command == ("rate", "set"):
        kitty.set_rate(args.currency, args.rate)
    elif args.command == "balances":
        return emit(kitty.balances())
    elif args.command == "settle":
        return emit(kitty.settle())
    elif args.command == "history":
        return emit(kitty.history(args.name))
    elif args.command == "report":
        return emit(kitty.report())
    elif args.command == "export":
        try:
            with open(args.file, "w", newline="", encoding="utf-8") as f:
                writer = csv.DictWriter(f, fieldnames=EXPORT_COLUMNS)
                writer.writeheader()
                writer.writerows(kitty.export_rows())
        except OSError as e:
            raise KittyError(f"could not write {args.file}: {e}") from None
        return
    kitty.save()


def main(argv=None):
    args = build_parser().parse_args(argv)
    try:
        run(args)
    except KittyError as e:
        print(f"error: {e}", file=sys.stderr)
        return 1
    return 0
class KittyError(Exception):
    """A user-facing error: printed as a message, exits with status 1."""
"""The kitty data model: members, expenses, payments and the maths on top.

Money is stored in kitty.json as two-decimal strings. Foreign-currency
expenses and payments are converted to the base currency when they are
recorded, using the rate in effect at that moment, and the converted amount is
stored alongside the original. Changing a rate later only affects new entries.
"""

import json
import os
import re
import tempfile
from datetime import date, datetime
from decimal import Decimal

from kitty.errors import KittyError
from kitty.money import (
    allocate,
    convert,
    fmt,
    parse_amount,
    parse_currency,
    parse_positive_number,
    to_cents,
)

FILENAME = "kitty.json"
DEFAULT_CATEGORY = "other"
_DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def parse_date(text):
    if text is None:
        return date.today().isoformat()
    text = text.strip()
    try:
        if not _DATE_RE.match(text):
            raise ValueError
        datetime.strptime(text, "%Y-%m-%d")
    except ValueError:
        raise KittyError(f"invalid date {text!r}: expected YYYY-MM-DD") from None
    return text


def _parse_pairs(text, option):
    """Parse 'A=30,B=20' into [('A', '30'), ('B', '20')]."""
    pairs = []
    for item in text.split(","):
        name, sep, value = item.partition("=")
        name, value = name.strip(), value.strip()
        if not sep or not name or not value:
            raise KittyError(f"invalid {option} entry {item.strip()!r}: expected NAME=VALUE")
        pairs.append((name, value))
    return pairs


class Kitty:
    def __init__(self, data, path):
        self.data = data
        self.path = path

    # ----- storage -----

    @classmethod
    def create(cls, base_currency, directory="."):
        path = os.path.join(directory, FILENAME)
        if os.path.exists(path):
            raise KittyError(f"{FILENAME} already exists here; refusing to overwrite it")
        data = {
            "version": 1,
            "base_currency": parse_currency(base_currency),
            "members": [],
            "rates": {},
            "expenses": [],
            "payments": [],
            "next_expense_id": 1,
            "next_seq": 1,
        }
        kitty = cls(data, path)
        kitty.save()
        return kitty

    @classmethod
    def load(cls, directory="."):
        path = os.path.join(directory, FILENAME)
        try:
            with open(path, encoding="utf-8") as f:
                data = json.load(f)
        except FileNotFoundError:
            raise KittyError(f"no {FILENAME} here; run 'init CURRENCY' first") from None
        except (OSError, ValueError) as e:
            raise KittyError(f"could not read {FILENAME}: {e}") from None
        required = {"base_currency", "members", "rates", "expenses", "payments",
                    "next_expense_id", "next_seq"}
        if not isinstance(data, dict) or not required <= data.keys():
            raise KittyError(f"{FILENAME} is not a valid kitty file")
        return cls(data, path)

    def save(self):
        # Write to a temporary file and rename it over the original, so an
        # interrupted write can never leave a half-written kitty.json behind.
        directory = os.path.dirname(os.path.abspath(self.path))
        try:
            fd, tmp = tempfile.mkstemp(dir=directory, prefix=".kitty-", suffix=".json")
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(self.data, f, indent=2, ensure_ascii=False)
                f.write("\n")
            os.replace(tmp, self.path)
        except OSError as e:
            raise KittyError(f"could not write {FILENAME}: {e}") from None

    # ----- helpers -----

    @property
    def base(self):
        return self.data["base_currency"]

    @property
    def members(self):
        return self.data["members"]

    def _resolve(self, name):
        """Return the member's name as first added, matching case-insensitively."""
        wanted = name.strip().casefold()
        for member in self.members:
            if member.casefold() == wanted:
                return member
        raise KittyError(f"unknown member {name.strip()!r}")

    def _next_seq(self):
        seq = self.data["next_seq"]
        self.data["next_seq"] = seq + 1
        return seq

    def _to_base(self, cents, currency):
        if currency == self.base:
            return cents
        rate = self.data["rates"].get(currency)
        if rate is None:
            raise KittyError(
                f"no exchange rate for {currency}; set one with 'rate set {currency} RATE'"
            )
        return convert(cents, Decimal(rate))

    def _referenced(self, name):
        for e in self.data["expenses"]:
            if e["payer"] == name or name in e["shares"]:
                return True
        return any(p["from"] == name or p["to"] == name for p in self.data["payments"])

    # ----- members -----

    def add_member(self, name):
        name = name.strip()
        if not name:
            raise KittyError("member name cannot be empty")
        if any(c in name for c in ",="):
            raise KittyError(f"invalid member name {name!r}: cannot contain ',' or '='")
        for existing in self.members:
            if existing.casefold() == name.casefold():
                raise KittyError(f"member {existing!r} already exists")
        self.members.append(name)

    def remove_member(self, name):
        name = self._resolve(name)
        if self._referenced(name):
            raise KittyError(
                f"cannot remove {name!r}: they appear in recorded expenses or payments"
            )
        self.members.remove(name)

    # ----- rates -----

    def set_rate(self, currency, rate):
        currency = parse_currency(currency)
        if currency == self.base:
            raise KittyError(f"{currency} is the base currency; its rate is always 1")
        self.data["rates"][currency] = str(parse_positive_number(rate, "rate"))

    # ----- expenses -----

    def add_expense(self, payer, amount, description, among=None, exact=None,
                    shares=None, percent=None, currency=None, when=None, category=None):
        payer = self._resolve(payer)
        description = description.strip()
        if not description:
            raise KittyError("description cannot be empty")
        cents = parse_amount(amount)
        currency = parse_currency(currency) if currency else self.base
        when = parse_date(when)
        category = (category or DEFAULT_CATEGORY).strip().lower()
        if not category:
            raise KittyError("category cannot be empty")

        given = [o for o, v in (("--among", among), ("--exact", exact),
                                ("--shares", shares), ("--percent", percent)) if v is not None]
        if len(given) > 1:
            raise KittyError(f"use only one of {', '.join(given)}")

        if exact is not None:
            pairs = [(n, parse_amount(v, f"exact amount for {n}"))
                     for n, v in _parse_pairs(exact, "--exact")]
            total = sum(v for _, v in pairs)
            if total != cents:
                raise KittyError(
                    f"--exact amounts add up to {fmt(total)} but the expense is {fmt(cents)}"
                )
            weights = [(n, Decimal(v)) for n, v in pairs]
        elif shares is not None:
            weights = [(n, parse_positive_number(v, f"share for {n}"))
                       for n, v in _parse_pairs(shares, "--shares")]
        elif percent is not None:
            weights = [(n, parse_positive_number(v, f"percent for {n}"))
                       for n, v in _parse_pairs(percent, "--percent")]
            total = sum(w for _, w in weights)
            if total != 100:
                raise KittyError(f"--percent values add up to {total}, not 100")
        else:
            if among is not None:
                names = [n.strip() for n in among.split(",")]
                if any(not n for n in names):
                    raise KittyError(f"invalid --among list {among!r}")
            else:
                names = list(self.members)
            weights = [(n, Decimal(1)) for n in names]

        if not weights:
            raise KittyError("nobody to split the expense among; add members first")
        weights = [(self._resolve(n), w) for n, w in weights]
        seen = set()
        for name, _ in weights:
            if name in seen:
                raise KittyError(f"{name!r} is listed more than once")
            seen.add(name)

        base_cents = self._to_base(cents, currency)
        split = allocate(base_cents, weights)
        expense = {
            "id": self.data["next_expense_id"],
            "seq": self._next_seq(),
            "date": when,
            "payer": payer,
            "description": description,
            "amount": fmt(cents),
            "currency": currency,
            "base_amount": fmt(base_cents),
            "category": category,
            "shares": {n: fmt(c) for n, c in split.items()},
        }
        self.data["next_expense_id"] += 1
        self.data["expenses"].append(expense)
        return expense["id"]

    def remove_expense(self, expense_id):
        try:
            wanted = int(expense_id)
        except ValueError:
            raise KittyError(f"invalid expense ID {expense_id!r}") from None
        for i, e in enumerate(self.data["expenses"]):
            if e["id"] == wanted:
                del self.data["expenses"][i]
                return
        raise KittyError(f"no expense with ID {wanted}")

    def list_expenses(self):
        return [
            {k: e[k] for k in ("id", "date", "payer", "description", "amount", "currency",
                               "base_amount", "category", "shares")}
            for e in sorted(self.data["expenses"], key=lambda e: e["id"])
        ]

    # ----- payments -----

    def add_payment(self, sender, recipient, amount, currency=None, when=None):
        sender = self._resolve(sender)
        recipient = self._resolve(recipient)
        if sender == recipient:
            raise KittyError("a payment needs two different people")
        cents = parse_amount(amount)
        currency = parse_currency(currency) if currency else self.base
        when = parse_date(when)
        self.data["payments"].append({
            "seq": self._next_seq(),
            "date": when,
            "from": sender,
            "to": recipient,
            "amount": fmt(cents),
            "currency": currency,
            "base_amount": fmt(self._to_base(cents, currency)),
        })

    # ----- reports -----

    def _events(self):
        """Every (date, seq, description, {member: change in cents}, payment or None),
        in date order, ties broken by the order they were recorded."""
        events = []
        for e in self.data["expenses"]:
            changes = {n: -to_cents(s) for n, s in e["shares"].items()}
            changes[e["payer"]] = changes.get(e["payer"], 0) + to_cents(e["base_amount"])
            events.append((e["date"], e["seq"], e["description"], changes, None))
        for p in self.data["payments"]:
            cents = to_cents(p["base_amount"])
            events.append((p["date"], p["seq"], None, {p["from"]: cents, p["to"]: -cents}, p))
        events.sort(key=lambda ev: (ev[0], ev[1]))
        return events

    def balance_cents(self):
        balances = {n: 0 for n in self.members}
        for _, _, _, changes, _ in self._events():
            for name, cents in changes.items():
                balances[name] = balances.get(name, 0) + cents
        return balances

    def balances(self):
        return {n: fmt(c) for n, c in self.balance_cents().items()}

    def settle(self):
        """Greedy settlement: the biggest debtor pays the biggest creditor, repeat.

        Ties for the biggest debtor or creditor go to whoever comes first
        alphabetically, ignoring case. Produces at most (number of members - 1)
        payments.
        """
        balances = self.balance_cents()
        creditors = [[c, n] for n, c in balances.items() if c > 0]
        debtors = [[-c, n] for n, c in balances.items() if c < 0]
        transfers = []
        while creditors and debtors:
            creditors.sort(key=lambda x: (-x[0], x[1].casefold()))
            debtors.sort(key=lambda x: (-x[0], x[1].casefold()))
            credit, debt = creditors[0], debtors[0]
            amount = min(credit[0], debt[0])
            transfers.append({"from": debt[1], "to": credit[1], "amount": fmt(amount)})
            credit[0] -= amount
            debt[0] -= amount
            creditors = [c for c in creditors if c[0] > 0]
            debtors = [d for d in debtors if d[0] > 0]
        return transfers

    def history(self, name):
        name = self._resolve(name)
        rows = []
        balance = 0
        for when, _, description, changes, payment in self._events():
            if name not in changes:
                continue
            if payment is not None:
                if payment["from"] == name:
                    description = f"Payment to {payment['to']}"
                else:
                    description = f"Payment from {payment['from']}"
            balance += changes[name]
            rows.append({"date": when, "description": description,
                         "change": fmt(changes[name]), "balance": fmt(balance)})
        return rows

    def report(self):
        totals = {}
        for e in self.data["expenses"]:
            per_member = totals.setdefault(e["category"], {})
            for name, share in e["shares"].items():
                per_member[name] = per_member.get(name, 0) + to_cents(share)
        order = {n: i for i, n in enumerate(self.members)}
        return {
            category: {n: fmt(c) for n, c in sorted(per_member.items(),
                                                     key=lambda kv: order.get(kv[0], 0))}
            for category, per_member in sorted(totals.items())
        }

    def export_rows(self):
        return [
            {k: e[k] for k in ("id", "date", "payer", "description", "amount", "currency",
                               "category", "base_amount")}
            for e in sorted(self.data["expenses"], key=lambda e: e["id"])
        ]
"""Parsing, rounding and splitting of money amounts.

All amounts are handled internally as integer cents so that splits always add
up exactly and balances always sum to zero.
"""

import re
from decimal import ROUND_FLOOR, ROUND_HALF_UP, Decimal, localcontext

from kitty.errors import KittyError

_AMOUNT_RE = re.compile(r"^\d+(\.\d{1,2})?$")
_NUMBER_RE = re.compile(r"^\d+(\.\d+)?$")
_CURRENCY_RE = re.compile(r"^[A-Z]{3}$")

CENT = Decimal("0.01")


def parse_amount(text, what="amount"):
    """Parse a positive amount with at most two decimals into cents."""
    text = text.strip()
    if not _AMOUNT_RE.match(text):
        raise KittyError(
            f"invalid {what} {text!r}: expected a positive number with at most two decimals"
        )
    cents = int(Decimal(text) * 100)
    if cents <= 0:
        raise KittyError(f"invalid {what} {text!r}: must be greater than zero")
    return cents


def parse_positive_number(text, what):
    """Parse a positive decimal number of any precision (rates, shares, percents)."""
    text = text.strip()
    if not _NUMBER_RE.match(text):
        raise KittyError(f"invalid {what} {text!r}: expected a positive number")
    value = Decimal(text)
    if value <= 0:
        raise KittyError(f"invalid {what} {text!r}: must be greater than zero")
    return value


def parse_currency(text):
    code = text.strip().upper()
    if not _CURRENCY_RE.match(code):
        raise KittyError(f"invalid currency {text!r}: expected a three-letter code like EUR")
    return code


def fmt(cents):
    """Format cents as a string with two decimals, e.g. -2070 -> '-20.70'."""
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return f"{sign}{cents // 100}.{cents % 100:02d}"


def to_cents(text):
    """Convert a stored two-decimal string back to cents."""
    return int(Decimal(text) * 100)


def convert(cents, rate):
    """Convert cents at the given rate, rounding half up to the nearest cent."""
    value = (Decimal(cents) / 100 * rate).quantize(CENT, rounding=ROUND_HALF_UP)
    return int(value * 100)


def allocate(total, weights):
    """Split `total` cents in proportion to `weights` (a list of (name, weight)).

    Each part is rounded down to the cent, then the leftover cents (always
    fewer than the number of people) go one each to people in the order given,
    so the parts always add up to `total` exactly.
    """
    with localcontext() as ctx:
        ctx.prec = 50
        weight_sum = sum(w for _, w in weights)
        parts = {
            name: int((Decimal(total) * weight / weight_sum).to_integral_value(rounding=ROUND_FLOOR))
            for name, weight in weights
        }
    leftover = total - sum(parts.values())
    for name, _ in weights[:leftover]:
        parts[name] += 1
    return parts
